              parser, [], 'Option username is mandatory.', [], 'username');
        });

        test('throw if no mandatory args', () {
          var parser = ArgParser();
          parser.addOption('test');
          parser.addOption('username', mandatory: true);
          throwsArgParserException(parser, ['--test', 'test'],
